type Cents = bigint & { readonly __brand: 'Cents' };
type Money<C extends CurrencyCode> = { readonly minor: Cents; readonly currency: C };

export const add = <C extends CurrencyCode>(a: Money<C>, b: Money<C>): Money<C> => ({
  minor: cents(a.minor + b.minor),      // the constructor validates range
  currency: a.currency,
});
